/**
 * A short "why is this source legit" line for the admin dashboard, pulled
 * from the same methodology_note that already holds the full text - not a
 * second thing to keep in sync. The full note is written for a human doing
 * real verification work; this is written for a human deciding whether to
 * open that full note at all. See app/admin/page.tsx.
 */

const MAX_LENGTH = 220;

/** Datasets generated by scripts/generate-datasets.ts carry this exact marker. */
const PERCEPTION_GAP_MARKER = /\*\*The perception-gap claim behind this dataset:\*\*\s*/;

export function shortJustification(methodologyNote: string | null): string {
  if (!methodologyNote) return "No methodology note on file.";

  const marker = methodologyNote.match(PERCEPTION_GAP_MARKER);
  const text = marker
    ? methodologyNote.slice(marker.index! + marker[0].length)
    : methodologyNote;

  const trimmed = text.trim().replace(/\s+/g, " ");
  if (trimmed.length <= MAX_LENGTH) return trimmed;

  // Cut at the last full word inside the limit, not mid-word.
  const cut = trimmed.slice(0, MAX_LENGTH);
  const lastSpace = cut.lastIndexOf(" ");
  return `${cut.slice(0, lastSpace > 0 ? lastSpace : MAX_LENGTH)}…`;
}
